with feeders as (
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__SCHEME_CODE))) as HUB_PRODUCT_HK
        , NO_OF_MEMBERS as CONFIGURED_MEMBER_COUNT
        , FAMILY_FLOATER as FAMILY_FLOATER_INDICATOR
        , AUTO_DEBIT as AUTO_DEBIT_ALLOWED_INDICATOR
        , AUTO_RENEWAL as AUTO_RENEWAL_INDICATOR
        , cast(null as varchar) as PORT_IN_BLOCKED_INDICATOR
        , cast(null as varchar) as NEW_BUSINESS_ADVANCE_ISSUANCE_DAYS
        , cast(null as varchar) as RENEWAL_ADVANCE_ISSUANCE_DAYS
        , cast(null as varchar) as AT_LEAST_ONE_COVERAGE_MANDATORY_INDICATOR
        , cast(null as varchar) as MULTIPLE_MANDATORY_COVERAGE_SELECTION_BLOCKED_INDICATOR
        , 'BJAZ_CTNGY_SCHEME_MST' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_scheme_mst') }}
    where (nullif(trim(SCHEME_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__SCHEME_CODE_PLAN_ID))) as HUB_PRODUCT_HK
        , cast(null as varchar) as CONFIGURED_MEMBER_COUNT
        , cast(null as varchar) as FAMILY_FLOATER_INDICATOR
        , cast(null as varchar) as AUTO_DEBIT_ALLOWED_INDICATOR
        , cast(null as varchar) as AUTO_RENEWAL_INDICATOR
        , APORT_BLOCKED as PORT_IN_BLOCKED_INDICATOR
        , DAYS_IN_ADVANCE as NEW_BUSINESS_ADVANCE_ISSUANCE_DAYS
        , RNW_DAYS_IN_ADVANCE as RENEWAL_ADVANCE_ISSUANCE_DAYS
        , ANY_ONE_CVR_MAND as AT_LEAST_ONE_COVERAGE_MANDATORY_INDICATOR
        , BLOCK_MULTIPLE_CVR_MAND as MULTIPLE_MANDATORY_COVERAGE_SELECTION_BLOCKED_INDICATOR
        , 'BJAZ_CTNGY_SCHEME_PLANS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_scheme_plans') }}
    where (nullif('SCHEMEPLAN:' || nullif(trim(SCHEME_CODE),'') || '|' || nullif(trim(PLAN_ID),''), 'SCHEMEPLAN:|')) is not null
),

resolved as (
    select
        HUB_PRODUCT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CONFIGURED_MEMBER_COUNT end) as CONFIGURED_MEMBER_COUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then FAMILY_FLOATER_INDICATOR end) as FAMILY_FLOATER_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AUTO_DEBIT_ALLOWED_INDICATOR end) as AUTO_DEBIT_ALLOWED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AUTO_RENEWAL_INDICATOR end) as AUTO_RENEWAL_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then PORT_IN_BLOCKED_INDICATOR end) as PORT_IN_BLOCKED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then NEW_BUSINESS_ADVANCE_ISSUANCE_DAYS end) as NEW_BUSINESS_ADVANCE_ISSUANCE_DAYS,
        max(case when SOURCE_RUN = 'opus_health_v2' then RENEWAL_ADVANCE_ISSUANCE_DAYS end) as RENEWAL_ADVANCE_ISSUANCE_DAYS,
        max(case when SOURCE_RUN = 'opus_health_v2' then AT_LEAST_ONE_COVERAGE_MANDATORY_INDICATOR end) as AT_LEAST_ONE_COVERAGE_MANDATORY_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then MULTIPLE_MANDATORY_COVERAGE_SELECTION_BLOCKED_INDICATOR end) as MULTIPLE_MANDATORY_COVERAGE_SELECTION_BLOCKED_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PRODUCT_HK
),

hashed as (
    select
        *,
        case when CONFIGURED_MEMBER_COUNT is not null or FAMILY_FLOATER_INDICATOR is not null or AUTO_DEBIT_ALLOWED_INDICATOR is not null or AUTO_RENEWAL_INDICATOR is not null or PORT_IN_BLOCKED_INDICATOR is not null or NEW_BUSINESS_ADVANCE_ISSUANCE_DAYS is not null or RENEWAL_ADVANCE_ISSUANCE_DAYS is not null or AT_LEAST_ONE_COVERAGE_MANDATORY_INDICATOR is not null or MULTIPLE_MANDATORY_COVERAGE_SELECTION_BLOCKED_INDICATOR is not null
                     then md5(upper(coalesce(cast(CONFIGURED_MEMBER_COUNT as varchar), '') || '|' || coalesce(cast(FAMILY_FLOATER_INDICATOR as varchar), '') || '|' || coalesce(cast(AUTO_DEBIT_ALLOWED_INDICATOR as varchar), '') || '|' || coalesce(cast(AUTO_RENEWAL_INDICATOR as varchar), '') || '|' || coalesce(cast(PORT_IN_BLOCKED_INDICATOR as varchar), '') || '|' || coalesce(cast(NEW_BUSINESS_ADVANCE_ISSUANCE_DAYS as varchar), '') || '|' || coalesce(cast(RENEWAL_ADVANCE_ISSUANCE_DAYS as varchar), '') || '|' || coalesce(cast(AT_LEAST_ONE_COVERAGE_MANDATORY_INDICATOR as varchar), '') || '|' || coalesce(cast(MULTIPLE_MANDATORY_COVERAGE_SELECTION_BLOCKED_INDICATOR as varchar), '')))
                end as SAT_PRODUCT_TERMS_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PRODUCT_HK is not null
  and SAT_PRODUCT_TERMS_HASHDIFF is not null
